import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.LeafNode;
import org.jsoup.nodes.TextNode;
import org.jsoup.nodes.Node;
import org.jsoup.parser.Parser;
import org.junit.Test;
import static org.junit.Assert.*;
import java.io.ByteArrayOutputStream;
import java.util.Arrays;
import org.jsoup.helper.Validate;

public class TextNodeTest {
    @Test
    public void nodeName() {
        TextNode textNode = new TextNode("Hello, World!");
        assertEquals("text", textNode.nodeName());
    }

    @Test
    public void nodeName_EmptyText() {
        TextNode textNode = new TextNode("");
        assertEquals("", textNode.nodeName());
    }

    @Test
    public void text() {
        TextNode textNode = new TextNode("Hello, World!");
        assertEquals("Hello, World!", textNode.text());
    }

    @Test
    public void text_EmptyText() {
        TextNode textNode = new TextNode("");
        assertEquals("", textNode.text());
    }

    @Test
    public void text_SplitText() {
        TextNode textNode = new TextNode("Hello, World!");
        TextNode splitTextNode = textNode.splitText(7);
        assertNotSame(textNode, splitTextNode);
        assertEquals("World!", splitTextNode.text());
    }

    @Test
    public void getWholeText() {
        TextNode textNode1 = new TextNode("Hello, World!");
        TextNode textNode2 = new TextNode(" Foo ");
        String wholeText = textNode1.getWholeText() + "" + textNode2.getWholeText();
        assertEquals("Hello, World! Foo ", wholeText);
    }

    @Test
    public void isBlank() {
        TextNode textNode = new TextNode("");
        assertTrue(textNode.isBlank());
    }

    @Test
    public void outerHtmlHead() throws IOException {
        TextNode textNode = new TextNode("<p>Hello, World!</p>");
        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        Appendable accum = outContent;
        int depth = 0;
        Document.OutputSettings settings = null; // not used
        textNode.outerHtmlHead(accum, depth, settings);
        assertEquals("<p>", outContent.toString());
    }

    @Test
    public void outerHtmlTail() {
        TextNode textNode = new TextNode("<p>Hello, World!</p>");
        Appendable accum = new StringBuilder();
        int depth = 0;
        Document.OutputSettings settings = null; // not used
        textNode.outerHtmlTail(accum, depth, settings);
        assertEquals("</p>", accum.toString());
    }

    @Test
    public void clone() {
        TextNode originalTextNode = new TextNode("Hello, World!");
        TextNode clonedTextNode = originalTextNode.clone();
        assertSame(originalTextNode, clonedTextNode);
    }

    @Test
    public void createFromEncoded() {
        TextNode textNode = TextNode.createFromEncoded("Hello, World!");
        assertEquals("Hello, World!", textNode.text());
    }

    @Test
    public void normaliseWhitespace() {
        String input = "   Hello, World!  ";
        assertEquals("Hello, World!", StringUtil.normaliseWhitespace(input));
    }

    @Test
    public void stripLeadingWhitespace() {
        String input = "     Hello, World!";
        assertEquals("Hello, World!", StringUtil.stripLeadingWhitespace(input));
    }

    @Test
    public void lastCharIsWhitespace() {
        StringBuilder sb = new StringBuilder();
        assertTrue(TextNode.lastCharIsWhitespace(sb));
        sb.append(' ');
        assertTrue(TextNode.lastCharIsWhitespace(sb));
        sb.append('!');
        assertFalse(TextNode.lastCharIsWhitespace(sb));
    }
}
